-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A claim uses its grade's rate with the latest
-- from-date on or before the claim's date; a claim dated before every such rate has no rate.
-- Each row gets its own id; from_key stands for the from-date (no from-date counting as the
-- earliest date) so a grade has at most one rate per from-date.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
ALTER TABLE rate ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD PRIMARY KEY (id);
ALTER TABLE rate ADD CONSTRAINT rate_grade_from_unique UNIQUE (sheet_id, grade, from_key);
-- Who opened a claim: the signed-in user's name, set when it is opened. Null while a draft, or
-- when it was voided without being opened. The user who opened a claim may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- The version of a person: bumped on each save, so an edit made from an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- A statement binds each of its person's counting (OPEN or SETTLED) claims to the figure it had
-- then: a stated claim shows and totals stated_due (null: n/a) until the person's next statement,
-- which rebinds their counting claims and leaves the rest unbound (stated false, live again).
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);

-- The statements taken of a person, in the order they were taken (by id): their due-total then
-- (null: n/a), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(12, 2),
    claims    INT            NOT NULL,
    taken_on  DATE           NOT NULL,
    taken_by  VARCHAR(255)   NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
-- The sheet's periods: a name, unique on the sheet without regard to case (name_key is the trimmed,
-- lower-cased name), and a from and to date, both inclusive, from on or before to. No two of a
-- sheet's periods overlap. A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A period can be closed. Closing fixes its due-total at that moment (closed_total), so later
-- changes to rates do not alter it; null while the period is open. No claim dated inside a
-- closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
-- Only a DRAFT claim can be edited; an OPEN claim is changed by voiding it and adding a new one.
-- A voided claim now keeps the number it was given when opened (still never reused); claims voided
-- before this change had theirs cleared and stay without one.
-- A person can be retired from a date; null while they are not. A person with a date set counts as
-- retired at once, whatever the date. No claim dated after it can be added to them, or edited to it.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- Whether the person is on hold: while held, their open claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- The sheet's settings by key: a setting with no row has no value (the clerk limit: no limit).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role the sheet assigns a user name; a name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
-- A sheet: everything else in the app is kept per sheet. A sheet is created the first time it is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_at TIMESTAMP    NOT NULL
);
-- The people a person has named as their patrons, each at most once, never the person themselves.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_once ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, person_id, id);
-- A person's grade is dated: each grade a person is given is kept with the date it applies from,
-- the first one (no from-date) from the beginning of time. The grade in force on a date is the one
-- with the latest from-date on or before it. from_key stands for the from-date (no from-date counting
-- as the earliest date) so a person has at most one grade per from-date.
CREATE TABLE person_grade (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from_unique ON person_grade (person_id, from_key);
