    c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's status log: one line per status it has had, in order (position 0 the oldest), each with
-- who made the change, the sheet's today then, and the claim's due as worked out at that moment (null
-- when n/a). A claim already stored has no log of its past.
CREATE TABLE claim_log (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    status   VARCHAR(20)    NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    due      DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
-- A person's holds are dated: each runs from its from-date to its to-date (none: open-ended), and a
-- person may have several over time. Only their open claims dated within a hold, and not bound by a
-- statement, are left out of the live totals. A person held before this has a hold from the
-- beginning of time (no from-date), open-ended.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
INSERT INTO person_hold (person_id) SELECT id FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate can carry a to-date: it is in force through that date and no longer. A claim dated after
-- the to-date of the rate that would apply to it (the latest from-date on or before the claim's
-- date) has no rate. A to-date is never before the rate's from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_not_before_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
-- Each sheet has its own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- Closing a period also fixes, at that moment, each person's due-total for it: the figures of their
-- counting claims dated in it. A person with no row (added after the close) has 0.00 for it.
-- Reopening removes the rows: the figures are live again.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The settings that carry a figure (the floor, the late percent, the sheet's and each grade's terms,
-- the clerk limit and the cap) are dated: each value is in force from its from-date until the next
-- from-date of the same key. A blank value clears the setting from its date (no limit, no cap, a
-- grade's own terms falling back to the sheet's). Before every from-date a key has its starting value.
CREATE TABLE sheet_setting_dated (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values already set stay in force on every date.
INSERT INTO sheet_setting_dated (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
DELETE FROM sheet_setting
    WHERE setting_key IN ('floor', 'late-pct', 'terms', 'terms-A', 'terms-B', 'terms-C', 'clerk-limit', 'cap');
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches
-- that date it counts in no total, is not overdue, cannot be settled and no statement binds it.
-- Null when the claim was never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- A claim's proofs count, raised by one at a time while it is not SETTLED or VOID. A claim whose due
-- is above the sheet's proof threshold cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INTEGER NOT NULL DEFAULT 0;
-- A viewer is a third role: it sees the sheet and changes nothing. The role check is widened by
-- rebuilding the table, as its check constraint has no name to drop.
CREATE TABLE sheet_role_v (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_v (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_v RENAME TO sheet_role;
-- The number of the claim an OPEN claim was split from; none for a claim that was not split off.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
-- The users watching a person, each at most once; the id keeps the order they started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX person_watch_once ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- A steward's delegation of the steward role to a user name for a from-date to a to-date, inclusive;
-- the id keeps the order they were made.
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name    VARCHAR(200) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(255) NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
-- A steward may archive a sheet: it stays visible, and every change on it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- A person may have their own terms, in days; none means the terms of their grade, else the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER;
-- People on a sheet, listed in the order they were added (by id). A grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- Opening a claim's editor locks the claim for other users until it is saved or cancelled, or the
-- sheet's today changes; none when the claim is not locked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(255);
-- A period can be soft-closed: its due-total (closed_total) and each person's due-total for it
-- (period_person_total) are fixed as a close fixes them, but claims dated inside it can still be
-- added, edited, opened, settled and voided. A soft-closed period is not closed; it can be closed
-- (fixing the figures afresh) or reopened.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A statement can be taken as of a date on or before the sheet's today: it binds the person's claims
-- as they stood at the end of that date, counting every change made while the sheet's today was on or
-- before it. So each change a figure depends on keeps the sheet's today it was made on (made_on; null:
-- made before this was kept, counting on every date).

-- The statement's date: the date it was taken as of, else the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN stated_on DATE;
UPDATE statement SET stated_on = taken_on;
ALTER TABLE statement ALTER COLUMN stated_on SET NOT NULL;

-- Each binding of a claim to a figure by a statement, and each loss of one (a later statement leaving it
-- out, its statement cancelled, its moving or splitting), oldest first.
CREATE TABLE claim_binding (
    claim_id   BIGINT  NOT NULL REFERENCES claim (id),
    position   INT     NOT NULL,
    on_date    DATE,
    stated     BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
INSERT INTO claim_binding (claim_id, position, stated, stated_due)
    SELECT id, 0, TRUE, stated_due FROM claim WHERE stated;

-- Each setting of a rate, oldest first: a rate set for a grade and from-date replaces the one before it.
CREATE TABLE rate_change (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(5, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_change_sheet ON rate_change (sheet_id, id);
INSERT INTO rate_change (sheet_id, grade, from_date, to_date, pct)
    SELECT sheet_id, grade, from_date, to_date, pct FROM rate ORDER BY id;

-- Each recording of a dated setting, oldest first: a value recorded for a key and from-date replaces
-- the one before it.
CREATE TABLE setting_change (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    made_on       DATE
);
CREATE INDEX setting_change_sheet ON setting_change (sheet_id, id);
INSERT INTO setting_change (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, from_date, setting_value FROM sheet_setting_dated;

-- When a person was added, given each grade, put on each hold and retired.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
-- What each sheet held at the end of each of its todays, for the as-of view: after every change
-- the sheet's rows are kept against the today the change was made on (the latest change on that
-- today wins), numbered in the order the changes were made. Not referenced by, nor referencing, the
-- sheet's own tables, so it is never part of what it records.
CREATE SEQUENCE sheet_history_seq;
CREATE TABLE sheet_history (
    sheet_id  VARCHAR(100) NOT NULL,
    today     DATE         NOT NULL,
    seq       BIGINT       NOT NULL,
    rows_data BLOB         NOT NULL,
    PRIMARY KEY (sheet_id, today)
);
CREATE INDEX sheet_history_seq_order ON sheet_history (sheet_id, seq);
-- An OPEN or PENDING claim can be reminded, once per sheet's today: the last day a reminder was
-- written for it. Null when it never was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- The sheet's holidays, each date at most once. A claim's due-by falling on one, when it is fixed,
-- moves to the next day that is not a holiday; due-by dates already fixed are kept as they are.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_once ON holiday (sheet_id, holiday_date);
-- A claim may carry an external reference, unique on its sheet without regard to case; null when it has none.
ALTER TABLE claim ADD COLUMN ref VARCHAR(220);
CREATE INDEX claim_ref_key ON claim (sheet_id, ref);
-- A claim may carry tags: lower-cased, sorted and comma separated; null when it has none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
-- Every tag ever used on a sheet, each once, kept when no claim carries it any more.
CREATE TABLE sheet_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(220) NOT NULL
);
CREATE UNIQUE INDEX sheet_tag_once ON sheet_tag (sheet_id, name);
-- The sheet's void reasons, each at most once. While a sheet has any, voiding a claim needs one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_once ON void_reason (sheet_id, reason);
-- The reason a claim was voided with; null when it is not void or was voided with none.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
-- A person's name is unique on the sheet, compared without regard to case and ignoring surrounding
-- spaces. Names are stored trimmed; name_key is the trimmed, lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A claim's comments, in the order they were written (position 0 the oldest), each with who wrote it
-- and the sheet's today then.
CREATE TABLE claim_comment (
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    position INT            NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    text     VARCHAR(1000)  NOT NULL,
    PRIMARY KEY (claim_id, position)
);
-- Who last edited a claim (through its form or its row's amount entry): the signed-in user's name,
-- set on each saved edit. Null when it was never edited. Like its opener, the user who last edited a
-- claim may not settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
-- Settle batches: a bulk settle that settles (or leaves pending) at least one claim is the sheet's
-- next batch, numbered 1, 2, ... Each claim it settled keeps the batch's number; null for a claim

